// Simple endless runner targeting <canvas id="game">
// Player: 20x20 square, auto‑runs right, jumps with Space, slides with Down Arrow

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // canvas not present
  const ctx = canvas.getContext('2d');

  const WIDTH = canvas.width = canvas.offsetWidth || 800;
  const HEIGHT = canvas.height = canvas.offsetHeight || 400;

  // Game constants
  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const PLAYER_SIZE = 20;
  const GROUND_Y = HEIGHT - PLAYER_SIZE;
  const SCROLL_SPEED = 4;

  let player = {
    x: 50,
    y: GROUND_Y,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    sliding: false,
  };

  const obstacles = [];
  let frames = 0;
  let gameOver = false;

  function spawnObstacle() {
    const height = Math.random() < 0.5 ? PLAYER_SIZE * 2 : PLAYER_SIZE;
    const width = PLAYER_SIZE * (Math.random() < 0.5 ? 1 : 2);
    const y = height > PLAYER_SIZE ? GROUND_Y - height : GROUND_Y - PLAYER_SIZE; // high vs low
    obstacles.push({ x: WIDTH, y, width, height });
  }

  function update() {
    if (gameOver) return;
    // player physics
    player.vy += GRAVITY;
    player.y += player.vy;
    if (player.y > GROUND_Y) {
      player.y = GROUND_Y;
      player.vy = 0;
    }
    // slide reduces height
    if (player.sliding) {
      player.height = PLAYER_SIZE / 2;
    } else {
      player.height = PLAYER_SIZE;
    }

    // move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= SCROLL_SPEED;
      // remove off‑screen
      if (o.x + o.width < 0) obstacles.splice(i, 1);
    }

    // spawn obstacles periodically
    if (frames % 120 === 0) spawnObstacle();

    // collision detection
    for (const o of obstacles) {
      const colliding =
        player.x < o.x + o.width &&
        player.x + player.width > o.x &&
        player.y < o.y + o.height &&
        player.y + player.height > o.y;
      if (colliding) {
        gameOver = true;
        break;
      }
    }

    frames++;
  }

  function draw() {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    // ground line
    ctx.fillStyle = '#555';
    ctx.fillRect(0, GROUND_Y + PLAYER_SIZE, WIDTH, 2);
    // player
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x, player.y, player.width, player.height);
    // obstacles
    ctx.fillStyle = '#f00';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.width, o.height);
    }
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', WIDTH / 2 - 80, HEIGHT / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // controls
  document.addEventListener('keydown', e => {
    if (e.code === 'Space' && player.y === GROUND_Y) {
      player.vy = JUMP_VELOCITY;
    }
    if (e.code === 'ArrowDown') {
      player.sliding = true;
    }
  });
  document.addEventListener('keyup', e => {
    if (e.code === 'ArrowDown') player.sliding = false;
  });

  // start
  loop();
})();
